// City keys retain the original Krasnodar-direction identifier for existing plots.
const farmLocations=[{id:'krasnodar',name:'Белореченск',note:'Краснодарский край · действующая ферма'},{id:'moscow',name:'Москва',note:'Ферма пока не подключена'},{id:'petersburg',name:'Санкт-Петербург',note:'Ферма пока не подключена'}];
function selectedFarmCity(){try{const id=localStorage.getItem('farm-city-'+(account?.id||'guest'));return farmLocations.some(c=>c.id===id)?id:'krasnodar'}catch{return 'krasnodar'}}
function cityPlots(){return myPlots().filter(p=>(p.city_id||'krasnodar')===selectedFarmCity())}
function changeFarmCity(id){if(!farmLocations.some(c=>c.id===id))return;try{localStorage.setItem('farm-city-'+(account?.id||'guest'),id)}catch{toast('Не удалось сохранить выбранный город')}modal.close();location.hash='home';render()}
function chooseFarmCity(){modalForm('Где ваше хозяйство?',`<p>Выберите город. На карте будут только его грядки.</p><div class="object-options">${farmLocations.map(c=>{const n=account?myPlots().filter(p=>(p.city_id||'krasnodar')===c.id).length:0;return `<button type="button" class="btn ${selectedFarmCity()===c.id?'':'light'}" onclick="changeFarmCity('${c.id}')"><b>${c.name}${selectedFarmCity()===c.id?' ✓':''}</b><br><small>${n?'Ваших грядок: '+n:c.note}</small></button>`}).join('')}</div>`,()=>{})}
const homeBeforeCities=cloudHome;
cloudHome=function(){if(!account)return homeBeforeCities();const city=farmLocations.find(c=>c.id===selectedFarmCity()),plots=cityPlots();if(!plots.length)return heading('Моё хозяйство · '+city.name,'')+`<section class="panel empty-farm"><h2>В этом городе у вас пока нет грядок</h2><p>${city.id==='krasnodar'?'Выберите размер — свободную грядку подберём автоматически.':'Ферма пока не подключена. Можно переключиться на Белореченск.'}</p>${city.id==='krasnodar'?'<a class="btn" href="#choose-bed">Арендовать грядку</a>':'<button class="btn" onclick="chooseFarmCity()">Выбрать другой город</button>'}</section>`;return homeBeforeCities()};
const beforeCityRender=render;render=function(){beforeCityRender();const route=location.hash.slice(1)||'home';if(route==='home'&&account){$('#app').innerHTML=cloudHome();$('#crumb').textContent='МОЁ ХОЗЯЙСТВО'}const bed=currentRoomPlot(),city=farmLocations.find(c=>c.id===(bed?.city_id||selectedFarmCity()));document.querySelector('header>span:nth-child(2)').innerHTML=`<button class="city-switch" onclick="chooseFarmCity()" aria-label="Выбрать город. Сейчас ${city?.name||'Белореченск'}">⌖ ${city?.name||'Белореченск'} <span aria-hidden="true">⌄</span></button>`};render();
